import{_ as t}from"./chunks/interactive-mode.GWxR--kb.js";import{_ as a,o,c as d,a2 as i}from"./chunks/framework.LX5S0jbT.js";const b=JSON.parse('{"title":"在终端中使用 Pi","description":"","frontmatter":{},"headers":[],"relativePath":"zh/usage.md","filePath":"zh/usage.md"}'),c={name:"zh/usage.md"};function r(l,e,s,n,h,p){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="在终端中使用-pi" tabindex="-1">在终端中使用 Pi <a class="header-anchor" href="#在终端中使用-pi" aria-label="Permalink to &quot;在终端中使用 Pi&quot;">​</a></h1><p>在要工作的文件夹中运行 <code>pi</code>。Pi 使用该文件夹发现文件、指令和配置，并对保存的会话进行分组。如果尚未安装 Pi 或选择模型，请先阅读<a href="./quickstart.html">快速开始</a>。</p><p>Pi 在加载项目资源之前可能会询问你是否信任工作文件夹。见<a href="./security.html#understand-project-trust">项目信任</a>。</p><p align="center"><img src="'+t+'" alt="Pi 交互模式：会话、编辑器和状态信息" width="750"></p><p>转录（transcript）区显示你的提示词、Pi 的响应、工具调用、结果和错误。你在编辑器中编写提示词和命令。页脚显示当前文件夹、会话、模型、上下文用量以及累计用量和费用。</p><h2 id="输入提示词" tabindex="-1">输入提示词 <a class="header-anchor" href="#输入提示词" aria-label="Permalink to &quot;输入提示词&quot;">​</a></h2><p>输入请求并按 <code>Enter</code> 发送。使用 <code>Shift+Enter</code> 添加一行，或按 <code>Ctrl+G</code> 在配置的外部编辑器中编写较长的提示词。</p><p>要包含文件或图片：</p><ul><li>输入 <code>@</code> 搜索文件并将其添加到提示词中。</li><li>按 <code>Tab</code> 补全路径。</li><li>粘贴图片，或将其拖入兼容的终端。</li></ul><h2 id="跟随-pi-的工作" tabindex="-1">跟随 Pi 的工作 <a class="header-anchor" href="#跟随-pi-的工作" aria-label="Permalink to &quot;跟随 Pi 的工作&quot;">​</a></h2><p>Pi 在工作时显示每次工具调用和结果。按 <code>Ctrl+O</code> 展开或收起工具输出。按 <code>Ctrl+T</code> 显示或隐藏思考块（thinking blocks）。</p><p>启动页眉列出 Pi 加载的指令和资源。编辑器边框指示当前的思考级别（thinking level）。页脚随模型使用上下文并上报用量而更新。</p><p>Pi 不会在每次工具调用前询问。请检查命令和被修改的文件，并在不受信任或无人值守的工作中使用沙箱。见<a href="./security.html">安全</a>。</p><h2 id="调整方向" tabindex="-1">调整方向 <a class="header-anchor" href="#调整方向" aria-label="Permalink to &quot;调整方向&quot;">​</a></h2><p>Pi 工作时你可以继续发送输入：</p><table tabindex="0"><thead><tr><th>目的</th><th>操作</th></tr></thead><tbody><tr><td>调整当前任务</td><td>输入消息并按 <code>Enter</code></td></tr><tr><td>在当前任务之后追加工作</td><td>输入消息并按 <code>Alt+Enter</code></td></tr><tr><td>将排队的消息返回编辑器</td><td>按 <code>Alt+Up</code></td></tr><tr><td>停止当前任务</td><td>按 <code>Escape</code></td></tr></tbody></table><p>用 <code>Enter</code> 发送的消息会等待当前响应及其工具调用完成，然后引导下一次响应。用 <code>Alt+Enter</code> 发送的后续消息会等待 Pi 完成当前任务。中止操作将排队的消息返回编辑器。</p><p>Windows Terminal 保留了一些 Alt 快捷键。Windows 上的替代方案见<a href="./terminal-setup.html">终端配置</a>。</p><h2 id="更改模型或设置" tabindex="-1">更改模型或设置 <a class="header-anchor" href="#更改模型或设置" aria-label="Permalink to &quot;更改模型或设置&quot;">​</a></h2><p>输入 <code>/</code> 搜索可用命令。最常用的命令有：</p><ul><li><code>/model</code> 选择模型。按 <code>Ctrl+L</code> 打开相同的选择器。</li><li><code>/thinking</code> 选择当前模型使用的推理量。按 <code>Shift+Tab</code> 在支持的级别间循环。</li><li><code>/login</code> 和 <code>/logout</code> 管理提供商（provider）访问。</li><li><code>/settings</code> 修改常用偏好。</li></ul><p>提示词模板、技能（skill）和扩展（extension）可以在同一菜单中添加更多命令。见<a href="./models.html">选择模型</a>、<a href="./configuration.html">配置</a>或完整的<a href="./slash-commands.html">斜杠命令参考</a>。</p><h2 id="继续或重新开始" tabindex="-1">继续或重新开始 <a class="header-anchor" href="#继续或重新开始" aria-label="Permalink to &quot;继续或重新开始&quot;">​</a></h2><p>除非禁用了会话持久化，Pi 会自动保存会话。</p><ul><li><code>/new</code> 开始新会话。</li><li><code>/resume</code> 打开另一个已保存的会话。</li><li><code>/name</code> 为当前会话起一个可识别的名称。</li><li><code>/session</code> 显示会话的文件、ID、消息数、token 用量和费用。</li></ul><p>想在不丢失现有工作的前提下探索另一种方案时，使用 <code>/tree</code>、<code>/fork</code> 或 <code>/clone</code>。使用 <code>/compact</code> 减少发送给模型的对话历史。这些工作流见<a href="./sessions.html">会话与上下文</a>。</p><p>离开 Pi 后，在同一文件夹中运行 <code>pi --continue</code> 可恢复其最近的会话。</p><h2 id="运行终端命令" tabindex="-1">运行终端命令 <a class="header-anchor" href="#运行终端命令" aria-label="Permalink to &quot;运行终端命令&quot;">​</a></h2><p>在命令前加 <code>!</code> 前缀来运行它，并将其输出包含在对话中：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!git status</span></span></code></pre></div><p>如果希望运行命令但不把输出发送给模型，使用 <code>!!</code>。</p><h2 id="复制、导出或分享结果" tabindex="-1">复制、导出或分享结果 <a class="header-anchor" href="#复制、导出或分享结果" aria-label="Permalink to &quot;复制、导出或分享结果&quot;">​</a></h2><p>按 <code>Ctrl+X</code> 或运行 <code>/copy</code> 复制最近一条助手响应。使用 <code>/export</code> 将会话保存为 HTML 或 JSONL。</p><p>使用 <code>/share</code> 上传会话并获取查看链接。默认情况下，Radius 认证使该内容对你的 Radius 组织可见；否则 Pi 会通过 GitHub CLI 创建私有的 GitHub gist。<a href="./settings.html#sessions-and-context"><code>sessionShareDestination</code></a> 设置可以强制指定其中一种目标。分享前请先检查会话，因为它可能包含提示词、工具输出、文件内容以及对话中暴露的凭据。</p><h2 id="调整终端" tabindex="-1">调整终端 <a class="header-anchor" href="#调整终端" aria-label="Permalink to &quot;调整终端&quot;">​</a></h2><p>默认的全屏模式让编辑器和状态区域固定，转录区在终端窗口内滚动。常规模式使用终端自身的滚动缓冲区。通过 <code>/settings</code> 或 <code>--tui-mode</code> 选择模式。</p><p>终端对鼠标输入、键盘快捷键和内联图片的支持各不相同。平台专属配置见<a href="./terminal-setup.html">终端配置</a>，所有可配置的快捷键见<a href="./keybindings.html">快捷键</a>。运行 <code>/hotkeys</code> 查看当前会话中生效的快捷键。</p><h2 id="收集诊断信息" tabindex="-1">收集诊断信息 <a class="header-anchor" href="#收集诊断信息" aria-label="Permalink to &quot;收集诊断信息&quot;">​</a></h2><p>排查终端渲染或会话状态问题时，运行 <code>/debug</code>。Pi 会将渲染的终端行和当前会话消息写入 <a href="./configuration.html#agent-directory">agent 目录</a>下的 <code>pi-debug.log</code>。</p><p>分享该文件前先检查内容。它可能包含提示词、模型响应、工具输出、文件内容和终端数据。</p>',40)])])}const f=a(c,[["render",r]]);export{b as __pageData,f as default};
